CREATE TABLE IF NOT EXISTS script_master (scrip_code INTEGER PRIMARY KEY, trading_symbol VARCHAR(255) NOT NULL, exchange VARCHAR(255), instrument_type VARCHAR(255), strike_price DOUBLE PRECISION, expiry VARCHAR(255), lot_size INTEGER, option_type VARCHAR(255));
CREATE TABLE IF NOT EXISTS mstock_instrument_master (instrument_token BIGINT PRIMARY KEY, instrument_key VARCHAR(255) NOT NULL UNIQUE, trading_symbol VARCHAR(255) NOT NULL, name VARCHAR(255), exchange VARCHAR(255), segment VARCHAR(255), instrument_type VARCHAR(255), exchange_token VARCHAR(255), last_price DOUBLE PRECISION, expiry VARCHAR(255), strike DOUBLE PRECISION, tick_size DOUBLE PRECISION, lot_size INTEGER, fetched_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS shoonya_instrument_master (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, instrument_key VARCHAR(512) NOT NULL UNIQUE, exchange VARCHAR(32) NOT NULL, token VARCHAR(64) NOT NULL, trading_symbol VARCHAR(512) NOT NULL, symbol VARCHAR(255), expiry VARCHAR(255), instrument VARCHAR(255), option_type VARCHAR(255), strike_price DOUBLE PRECISION, lot_size INTEGER, tick_size DOUBLE PRECISION, fetched_at TIMESTAMP NOT NULL);
